/* Offline packet-local adapter of the frame layer; protocol state belongs to ReceiveAudit. */
package de.rub.nds.tlsattacker.core.layer.impl;
import de.rub.nds.tlsattacker.core.quic.frame.*;
import de.rub.nds.tlsattacker.core.quic.constants.QuicFrameType;
public class QuicFrameLayer {
 public static QuicFrame create(long type) {
  QuicFrameType frameType=QuicFrameType.getFrameType(type);
  switch(frameType) {
   case ACK_FRAME: return new AckFrame(false);
   case ACK_FRAME_WITH_ECN: return new AckFrame(true);
   case CONNECTION_CLOSE_QUIC_FRAME: return new ConnectionCloseFrame(true);
   case CONNECTION_CLOSE_APPLICATION_FRAME: return new ConnectionCloseFrame(false);
   case CRYPTO_FRAME: return new CryptoFrame();
   case HANDSHAKE_DONE_FRAME: return new HandshakeDoneFrame();
   case NEW_CONNECTION_ID_FRAME: return new NewConnectionIdFrame();
   case RETIRE_CONNECTION_ID: return new RetireConnectionIdFrame();
   case NEW_TOKEN_FRAME: return new NewTokenFrame();
   case PADDING_FRAME: return new PaddingFrame();
   case PATH_CHALLENGE_FRAME: return new PathChallengeFrame();
   case PATH_RESPONSE_FRAME: return new PathResponseFrame();
   case PING_FRAME: return new PingFrame();
   case STREAM_FRAME: case STREAM_FRAME_OFF_LEN_FIN: case STREAM_FRAME_OFF_LEN: case STREAM_FRAME_LEN_FIN: case STREAM_FRAME_OFF_FIN: case STREAM_FRAME_FIN: case STREAM_FRAME_LEN: case STREAM_FRAME_OFF: return new StreamFrame(frameType);
   case RESET_STREAM_FRAME: return new ResetStreamFrame();
   case STOP_SENDING_FRAME: return new StopSendingFrame();
   case MAX_DATA_FRAME: return new MaxDataFrame();
   case MAX_STREAM_DATA_FRAME: return new MaxStreamDataFrame();
   case MAX_STREAMS_UNI_FRAME: return new MaxStreamsFrame(false);
   case MAX_STREAMS_BIDI_FRAME: return new MaxStreamsFrame(true);
   case DATA_BLOCKED_FRAME: return new DataBlockedFrame();
   case STREAM_DATA_BLOCKED_FRAME: return new StreamDataBlockedFrame();
   case STREAMS_BLOCKED_UNI_FRAME: return new StreamsBlockedFrame(false);
   case STREAMS_BLOCKED_BIDI_FRAME: return new StreamsBlockedFrame(true);
   case DATAGRAM_FRAME: return new DatagramFrame(false);
   case DATAGRAM_FRAME_LEN: return new DatagramFrame(true);
   default:return null;
  }
 }
}
